145	func (m pickerModel) view() string {
146		var b strings.Builder
147	
148		b.WriteString(renderPickerHeader(m.styles))
149		b.WriteString(m.renderFilterChips())
150		b.WriteString("\n")
151	
152		if len(m.skills) == 0 {
153			b.WriteString("  No skills found. Create skill files in .claude/skills/ or .gemini/agents/\n")
154			return b.String()
155		}
156	
157		// If all skills have zero sessions, show an actionable empty state.
158		if !m.hasAnySessionData() {
159			fmt.Fprintf(&b, "  %d skills discovered, but no session data found.\n\n", len(m.skills))
160			b.WriteString(m.styles.render(m.styles.dim, "  To populate skill analytics:"))
161			b.WriteString("\n")
162			b.WriteString(m.styles.render(m.styles.dim, "    1. Run sessions with your agent (creates checkpoints)"))
163			b.WriteString("\n")
164			b.WriteString(m.styles.render(m.styles.dim, "    2. Run `entire insights` to extract skill signals"))
165			b.WriteString("\n")
166			b.WriteString(m.styles.render(m.styles.dim, "    3. Re-open this dashboard"))
167			b.WriteString("\n\n")
168			b.WriteString(m.styles.render(m.styles.sectionHeader, "  Skills found:"))
169			b.WriteString("\n")
170			for _, skill := range m.skills {
171				fmt.Fprintf(&b, "    %s  %s\n",
172					m.styles.render(m.styles.bold, skill.Name),
173					m.styles.render(m.styles.dim, skill.SourceAgent))
174			}
175			return b.String()
176		}
177	
178		// Column widths
179		const colName = 24
180		const colSessions = 10
181		const colFreq = 12
182		const colScore = 10
183	
184		// Column headers
185		header := "  " + padRight("Name", colName) +
186			padRight("Sessions", colSessions) + padRight("Freq", colFreq) + padRight("Score", colScore)
187		b.WriteString(m.styles.render(m.styles.dim, header))
188		b.WriteString("\n")
189		b.WriteString(m.styles.render(m.styles.dim, "  "+strings.Repeat("\u2500", colName+colSessions+colFreq+colScore)))
190		b.WriteString("\n")
191	
192		for i, skill := range m.skills {
193			statsKey := skill.Name + "|" + skill.SourceAgent
194			st := m.stats[statsKey]
195	
196			isSelected := i == m.selected
197			marker := "  "
198			if isSelected {
199				marker = m.styles.render(m.styles.selected, "\u25b8 ")
200			}
201	
202			sessions := 0
203			freqStr := m.styles.render(m.styles.dim, "0.0/wk")
204			scoreStr := m.styles.render(m.styles.dim, "\u2500")
205			if st != nil {
206				sessions = st.TotalSessions
207				freqStr = formatFrequency(m.styles, st.SessionsPerWeek)
208				if st.TotalSessions > 0 {
209					scoreStr = fmt.Sprintf("%.0f", st.AvgScore)
210				}
211			}
212	
213			// Render name with style, then pad to visible width.
214			var nameStr string
215			if isSelected {
216				nameStr = m.styles.render(m.styles.selectedRow, skill.Name)
217			} else {
218				nameStr = skill.Name
219			}
220	
221			sessStr := strconv.Itoa(sessions)
222			if sessions == 0 {
223				sessStr = m.styles.render(m.styles.dim, "0")
224			}
225	
226			line := marker +
227				padRight(nameStr, colName) +
228				padRight(sessStr, colSessions) +
229				padRight(freqStr, colFreq) +
230				padRight(scoreStr, colScore)
231	
232			b.WriteString(line)
233			b.WriteString("\n")
234		}
235	
236		return b.String()
237	}
238	
239	func (m pickerModel) renderFilterChips() string {
240		labels := [3]string{"All", "Repo", "Personal"}
241		var chips []string
242		for i, label := range labels {
243			if i == m.scope {
244				chips = append(chips, m.styles.render(m.styles.chipActive, "[ "+label+" ]"))
245			} else {
246				chips = append(chips, m.styles.render(m.styles.chipDisabled, "  "+label+"  "))
247			}
248		}
249		return "  " + strings.Join(chips, " ") + "\n"
250	}
251	
252	func formatFrequency(s tuiStyles, perWeek float64) string {
253		rate := fmt.Sprintf("%.1f/wk", perWeek)
254		switch {
255		case perWeek > 1.0:
256			return s.render(s.success, "\u25b2") + " " + rate
257		case perWeek < 0.5:
258			return s.render(s.friction, "\u25bc") + " " + rate
259		default:
260			return s.render(s.dim, "\u2500") + " " + rate
261		}
262	}
