14		tea "github.com/charmbracelet/bubbletea"
15		"github.com/entireio/cli/cmd/entire/cli/insightsdb"
16		"github.com/entireio/cli/cmd/entire/cli/skilldb"
17		"github.com/entireio/cli/cmd/entire/cli/skillimprove"
18	)
19	
20	const (
21		screenPicker    = 0
22		screenDashboard = 1
23	
24		tabStats    = 0
25		tabFriction = 1
26		tabImprove  = 2
27	
28		maxWidth = 120
29	)
30	
31	//nolint:recvcheck // bubbletea pattern: value receivers for interface, pointer for mutation
32	type rootModel struct {
33		ctx       context.Context
34		screen    int
35		activeTab int
36	
37		// Current skill
38		selectedSkill *skilldb.SkillRow
39	
40		// Data sources
41		skillDB    *skilldb.SkillDB
42		insightsDB *insightsdb.InsightsDB
43		generator  *skillimprove.Generator
44		repoRoot   string
45	
46		// Sub-models
47		picker      pickerModel
48		statsTab    statsModel
49		frictionTab frictionModel
50		improveTab  improveModel
51	
52		// UI state
53		styles   tuiStyles
54		width    int
55		height   int
56		showHelp bool
57		errFlash string
58		err      error
59	}
60	
61	// Run launches the skill improvement TUI program.
62	func Run(ctx context.Context, skillDBPath, insightsDBPath, repoRoot string) error {
63		sdb, err := skilldb.Open(skillDBPath)
64		if err != nil {
65			return fmt.Errorf("open skill database: %w", err)
66		}
67		defer sdb.Close()
68	
69		idb, err := insightsdb.Open(insightsDBPath)
70		if err != nil {
71			return fmt.Errorf("open insights database: %w", err)
72		}
73		defer idb.Close()
74	
75		styles := newStyles()
76		m := rootModel{
77			ctx:        ctx,
78			styles:     styles,
79			width:      maxWidth,
80			skillDB:    sdb,
81			insightsDB: idb,
82			generator:  &skillimprove.Generator{},
83			repoRoot:   repoRoot,
84			picker:     newPickerModel(styles),
85			improveTab: newImproveModel(styles),
86		}
87	
88		p := tea.NewProgram(m, tea.WithAltScreen())
89		_, runErr := p.Run()
90		if runErr != nil {
91			return fmt.Errorf("run TUI: %w", runErr)
92		}
93		return nil
94	}
95	
96	func (m rootModel) Init() tea.Cmd {
97		return m.loadData()
98	}
99	
100	func (m rootModel) loadData() tea.Cmd {
101		return func() tea.Msg {
102			// Discover skills on disk.
103			discovered, err := skilldb.DiscoverSkills(m.repoRoot)
104			if err != nil {
105				return dataLoadedMsg{err: fmt.Errorf("discover skills: %w", err)}
106			}
107	
108			// Convert discovered skills to SkillRow for refresh.
109			rows := make([]skilldb.SkillRow, len(discovered))
110			now := time.Now().UTC()
111			for i, d := range discovered {
112				rows[i] = skilldb.SkillRow{
113					Name:         d.Name,
114					SourceAgent:  d.SourceAgent,
115					Path:         d.Path,
116					Kind:         d.Kind,
117					Scope:        d.Scope,
118					DiscoveredAt: now,
119					LastSeenAt:   now,
120				}
121			}
122	
123			// Refresh cache from insightsdb.
124			if _, err = m.skillDB.RefreshFromInsightsDB(m.ctx, m.insightsDB, rows, m.repoRoot); err != nil {
125				return dataLoadedMsg{err: fmt.Errorf("refresh skill cache: %w", err)}
126			}
127	
128			// Load stats for each discovered skill.
129			// Use rows directly (not ListSkills) to preserve Scope from discovery.
130			stats := make(map[string]*skilldb.SkillStatsResult, len(rows))
131			for _, skill := range rows {
132				st, statsErr := m.skillDB.SkillStats(m.ctx, skill.Name, skill.SourceAgent)
133				if statsErr != nil {
134					return dataLoadedMsg{err: fmt.Errorf("skill stats for %q: %w", skill.Name, statsErr)}
135				}
136				stats[skill.Name+"|"+skill.SourceAgent] = st
137			}
138	
139			return dataLoadedMsg{skills: rows, stats: stats}
140		}
141	}
142	
143	//nolint:ireturn // required by bubbletea Model interface
144	func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
145		switch msg := msg.(type) {
146		case tea.WindowSizeMsg:
147			return m.handleResize(msg)
148		case tea.KeyMsg:
149			return m.handleKeyMsg(msg)
150		case spinner.TickMsg:
151			return m.handleSpinnerTick(msg)
152		default:
153			return m.handleDataMsg(msg)
154		}
155	}
156	
157	//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
158	func (m rootModel) handleResize(msg tea.WindowSizeMsg) (tea.Model, tea.Cmd) {
159		m.width = min(msg.Width, maxWidth)
160		m.height = msg.Height
161		m.picker.setSize(m.width, m.contentHeight())
162		m.statsTab.setSize(m.width, m.contentHeight())
163		m.frictionTab.setSize(m.width, m.contentHeight())
164		m.improveTab.setSize(m.width, m.contentHeight())
165		return m, nil
166	}
167	
168	//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
169	func (m rootModel) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
170		// Always allow ctrl+c to quit.
171		if key.Matches(msg, globalKeyMap.Quit) && msg.String() == "ctrl+c" {
172			return m, tea.Quit
173		}
174	
175		if m.screen == screenPicker {
176			return m.handlePickerKeys(msg)
177		}
178		return m.handleDashboardKeys(msg)
179	}
180	
181	//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
182	func (m rootModel) handlePickerKeys(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
183		if key.Matches(msg, globalKeyMap.Quit) {
184			return m, tea.Quit
185		}
186		var cmd tea.Cmd
187		m.picker, cmd = m.picker.update(msg)
188		return m, cmd
189	}
190	
191	//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
192	func (m rootModel) handleDashboardKeys(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
193		switch {
194		case key.Matches(msg, globalKeyMap.Quit):
195			return m, tea.Quit
196		case key.Matches(msg, globalKeyMap.Help):
197			m.showHelp = !m.showHelp
198			return m, nil
199		case key.Matches(msg, globalKeyMap.TabNext):
200			m.activeTab = (m.activeTab + 1) % 3
201			return m, nil
202		case key.Matches(msg, globalKeyMap.TabPrev):
203			m.activeTab = (m.activeTab + 2) % 3
204			return m, nil
205		case key.Matches(msg, globalKeyMap.Tab1):
206			m.activeTab = tabStats
207			return m, nil
208		case key.Matches(msg, globalKeyMap.Tab2):
209			m.activeTab = tabFriction
210			return m, nil
211		case key.Matches(msg, globalKeyMap.Tab3):
212			m.activeTab = tabImprove
213			return m, nil
214		case key.Matches(msg, dashboardKeyMap.Back):
215			return m, func() tea.Msg { return backToPickerMsg{} }
216		case key.Matches(msg, dashboardKeyMap.Refresh):
217			return m, func() tea.Msg { return refreshMsg{} }
218		default:
219			return m.delegateToActiveTab(msg)
220		}
221	}
222	
223	//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
224	func (m rootModel) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
225		if m.improveTab.isGenerating {
226			var cmd tea.Cmd
227			m.improveTab.spinner, cmd = m.improveTab.spinner.Update(msg)
228			return m, cmd
229		}
230		return m, nil
231	}
232	
233	//nolint:ireturn,cyclop // returns tea.Model; message dispatch requires many cases
234	func (m rootModel) handleDataMsg(msg tea.Msg) (tea.Model, tea.Cmd) {
235		switch msg := msg.(type) {
236		case dataLoadedMsg:
237			if msg.err != nil {
238				m.err = msg.err
239				return m, nil
240			}
241			m.picker.setData(msg.skills, msg.stats)
242			return m, nil
243	
244		case skillSelectedMsg:
245			m.selectedSkill = &msg.skill
246			m.screen = screenDashboard
247			m.activeTab = tabStats
248			return m, m.loadSkillDetail(msg.skill)
249	
250		case skillDetailLoadedMsg:
251			if msg.err != nil {
252				return m, func() tea.Msg { return errorFlashMsg{text: msg.err.Error()} }
253			}
254			m.statsTab.setData(msg.stats, msg.sessions, msg.agents)
255			m.frictionTab.setData(msg.friction, msg.missing)
256			m.improveTab.setData(msg.improvements)
257			return m, nil
258	
259		case backToPickerMsg:
260			m.screen = screenPicker
261			m.selectedSkill = nil
262			m.activeTab = tabStats
263			m.showHelp = false
264			return m, nil
265	
266		case generateStartedMsg:
267			m.improveTab.isGenerating = true
268			return m, tea.Batch(m.improveTab.spinner.Tick, m.generateSuggestions())
269	
270		case generateDoneMsg:
271			m.improveTab.isGenerating = false
272			if msg.err != nil {
273				return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("generate failed: %v", msg.err)} }
274			}
275			m.improveTab.suggestions = msg.suggestions
276			m.improveTab.selected = 0
277			return m, nil
278	
279		case applyDiffMsg:
280			return m, m.applyDiff(msg.index)
281	
282		case applyDiffResultMsg:
283			return m.handleApplyResult(msg)
284	
285		case dismissSuggestionMsg:
286			m.removeSuggestion(msg.index)
287			return m, nil
288	
289		case refreshMsg:
290			return m, m.loadData()
291	
292		case errorFlashMsg:
293			m.errFlash = msg.text
294			return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearErrorMsg{} })
295	
296		case clearErrorMsg:
297			m.errFlash = ""
298			return m, nil
299	
300		default:
301			return m.delegateToActiveTab(msg)
302		}
303	}
304	
305	//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
306	func (m rootModel) handleApplyResult(msg applyDiffResultMsg) (tea.Model, tea.Cmd) {
307		if msg.err != nil {
308			return m, func() tea.Msg { return errorFlashMsg{text: fmt.Sprintf("apply failed: %v", msg.err)} }
309		}
310		m.removeSuggestion(msg.index)
311		return m, func() tea.Msg { return errorFlashMsg{text: "Diff applied successfully"} }
312	}
313	
314	func (m *rootModel) removeSuggestion(index int) {
315		if index < len(m.improveTab.suggestions) {
316			m.improveTab.suggestions = append(
317				m.improveTab.suggestions[:index],
318				m.improveTab.suggestions[index+1:]...,
319			)
320			if m.improveTab.selected >= len(m.improveTab.suggestions) && m.improveTab.selected > 0 {
321				m.improveTab.selected--
322			}
323		}
324	}
325	
326	//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
327	func (m rootModel) delegateToActiveTab(msg tea.Msg) (tea.Model, tea.Cmd) {
328		if m.screen != screenDashboard {
329			return m, nil
330		}
331		var cmd tea.Cmd
332		switch m.activeTab {
333		case tabStats:
334			m.statsTab, cmd = m.statsTab.update(msg)
335		case tabFriction:
336			m.frictionTab, cmd = m.frictionTab.update(msg)
337		case tabImprove:
338			m.improveTab, cmd = m.improveTab.update(msg)
339		}
340		return m, cmd
341	}
342	
343	func (m rootModel) View() string {
344		if m.err != nil {
345			return fmt.Sprintf("Error: %v\n\nCheck database paths and try again.", m.err)
346		}
347	
348		if m.screen == screenPicker && len(m.picker.skills) == 0 && m.picker.stats == nil {
349			return "Loading..."
350		}
351	
352		var b strings.Builder
353	
354		if m.screen == screenPicker {
355			b.WriteString(m.picker.view())
356			b.WriteString("\n")
