539	func (m rootModel) applyDiff(index int) tea.Cmd {
540		return func() tea.Msg {
541			if index >= len(m.improveTab.suggestions) || m.selectedSkill == nil {
542				return applyDiffResultMsg{index: index, err: errors.New("invalid suggestion index")}
543			}
544	
545			sug := m.improveTab.suggestions[index]
546			skillPath := filepath.Join(m.repoRoot, m.selectedSkill.Path)
547	
548			if err := skillimprove.ApplyDiff(skillPath, sug.Diff); err != nil {
549				return applyDiffResultMsg{index: index, err: fmt.Errorf("apply diff: %w", err)}
550			}
551	
552			// Record the applied improvement in the database.
553			imp := skilldb.SkillImprovement{
554				ID:          fmt.Sprintf("%d-%s", time.Now().UnixNano(), m.selectedSkill.Name),
555				SkillName:   m.selectedSkill.Name,
556				SourceAgent: m.selectedSkill.SourceAgent,
557				Title:       sug.Title,
558				Description: sug.Description,
559				Diff:        sug.Diff,
560				Priority:    sug.Priority,
561				Status:      "applied",
562				CreatedAt:   time.Now().UTC(),
563			}
564			appliedAt := time.Now().UTC()
565			imp.AppliedAt = &appliedAt
566	
567			if err := m.skillDB.InsertImprovement(m.ctx, imp); err != nil {
568				// Non-fatal: diff was applied but recording failed.
569				return applyDiffResultMsg{index: index, err: nil}
570			}
571	
572			return applyDiffResultMsg{index: index, err: nil}
573		}
574	}
