366	func PreviewSelection(snapshot Snapshot, prompt string, now time.Time) SelectionReport {
367		maxInjected := snapshot.MaxInjected
368		if maxInjected <= 0 {
369			maxInjected = DefaultMaxInjected
370		}
371	
372		promptTokens := tokenize(prompt)
373		if len(promptTokens) == 0 {
374			return SelectionReport{}
375		}
376	
377		candidates := make([]scoredCandidate, 0, len(snapshot.Records))
378		for _, record := range snapshot.Records {
379			signals := buildRecordMatchSignals(record)
380			primaryOverlap := tokenOverlap(promptTokens, signals.primaryTokens)
381			if !passesInjectionGate(record, primaryOverlap) {
382				continue
383			}
384			candidate := buildScoredCandidate(record, primaryOverlap, now)
385			if candidate.adjustedScore <= 0 {
386				continue
387			}
388			candidates = append(candidates, candidate)
389		}
390	
391		sort.SliceStable(candidates, func(i, j int) bool {
392			if candidates[i].adjustedScore != candidates[j].adjustedScore {
393				return candidates[i].adjustedScore > candidates[j].adjustedScore
394			}
395			if candidates[i].baseScore != candidates[j].baseScore {
396				return candidates[i].baseScore > candidates[j].baseScore
397			}
398			if candidates[i].record.Strength != candidates[j].record.Strength {
399				return candidates[i].record.Strength > candidates[j].record.Strength
400			}
401			return candidates[i].record.Title < candidates[j].record.Title
402		})
403	
404		matches := packSelectedCandidates(candidates, maxInjected)
405		return SelectionReport{
406			Matches: matches,
407			Skipped: explainSkippedCandidates(candidates, matches),
408		}
409	}
